solution:
const arrayLike = { 0: "a", 1: "b", 2: "c", length: 3 }
const arr = Array.from(arrayLike)
return {
  type: typeof arrayLike,
  converted: arr,
  mapResult: arr.map(x => x.toUpperCase())
}
